<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { NButton, NDrawer, NDrawerContent, NInput, NModal, NSelect, useDialog, useMessage } from 'naive-ui'
import PageHeader from '../components/PageHeader.vue'
import SectionCard from '../components/SectionCard.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { dataSource } from '../services'
import type { MemoryRecord } from '../types/domain'
import { localeText } from '../i18n'

const message = useMessage(); const dialog = useDialog()
const memories = ref<MemoryRecord[]>([]); const selected = ref<MemoryRecord|null>(null); const search = ref(''); const state = ref<string|null>(null); const compact = ref<{before:number;after:number;evidencePreserved:number}|null>(null)
onMounted(async()=>{memories.value=await dataSource.memories()})
const filtered=computed(()=>memories.value.filter(m=>(!state.value||m.state===state.value)&&(!search.value||`${m.claim} ${m.kind} ${m.scope}`.toLowerCase().includes(search.value.toLowerCase()))))
const transition=async(action:'confirm'|'contest'|'retract'|'archive')=>{if(!selected.value)return; const updated=await dataSource.transitionMemory(selected.value.id,action); selected.value=updated; const i=memories.value.findIndex(m=>m.id===updated.id);memories.value[i]=updated; const feedback={confirm:'Memory confirmed; a new revision was recorded',contest:'Memory marked as contested; a new revision was recorded',retract:'Memory retracted; a new revision was recorded',archive:'Memory archived; a new revision was recorded'}[action];message.success(localeText(feedback))}
const previewCompact=async()=>{compact.value=await dataSource.compactMemories()}
</script>

<template><div><PageHeader page="memories" eyebrow="CONTINUITY / GOVERNED"><NButton secondary size="small" @click="previewCompact">{{ $lt('Compact preview') }}</NButton><NButton type="primary" size="small">+ {{ $lt('Add candidate') }}</NButton></PageHeader>
  <div class="metric-grid memory-metrics"><article class="metric-card"><div class="metric-top"><span>{{ $lt('Confirmed') }}</span><i/></div><strong>{{ memories.filter(m=>m.state==='confirmed').length }}</strong><div class="metric-meta"><span>{{ $lt('trusted') }}</span><small>{{ $lt('with evidence') }}</small></div></article><article class="metric-card tone-warning"><div class="metric-top"><span>{{ $lt('Needs review') }}</span><i/></div><strong>{{ memories.filter(m=>['contested','stale'].includes(m.state)).length }}</strong><div class="metric-meta"><span>{{ $lt('attention') }}</span><small>{{ $lt('contested or stale') }}</small></div></article><article class="metric-card"><div class="metric-top"><span>{{ $lt('Evidence refs') }}</span><i/></div><strong>{{ memories.reduce((a,m)=>a+m.evidenceCount,0) }}</strong><div class="metric-meta"><span>{{ $lt('traceable') }}</span><small>{{ $lt('across current set') }}</small></div></article><article class="metric-card"><div class="metric-top"><span>{{ $lt('Cross-agent') }}</span><i/></div><strong>{{ memories.filter(m=>m.usedBy.length>1).length }}</strong><div class="metric-meta"><span>{{ $lt('shared') }}</span><small>{{ $lt('used by 2 agents') }}</small></div></article></div>
  <div class="filter-row"><NInput v-model:value="search" :placeholder="$lt('Search claim, scope, kind…')"/><NSelect v-model:value="state" clearable :placeholder="$lt('All states')" :options="[{label:$lt('Confirmed'),value:'confirmed'},{label:$lt('Contest'),value:'contested'},{label:$lt('Stale'),value:'stale'}]"/></div>
  <SectionCard :title="$lt('Project memory')" :subtitle="`${filtered.length} ${$lt('memories')} · ${$lt('evidence-backed lifecycle')}`" flush><table class="data-table"><thead><tr><th>{{ $lt('Claim') }}</th><th>{{ $lt('State') }}</th><th>{{ $lt('Priority') }}</th><th>{{ $lt('Confidence') }}</th><th>{{ $lt('Evidence') }}</th><th>{{ $lt('Used by') }}</th><th></th></tr></thead><tbody><tr v-for="memory in filtered" :key="memory.id"><td><div class="cell-title"><strong>{{ memory.claim }}</strong><small class="mono">{{ memory.id }} · {{ memory.kind }} · {{ memory.scope }}</small></div></td><td><StatusBadge :status="memory.state"/></td><td class="mono">P{{ memory.priority }}</td><td><strong>{{ Math.round(memory.confidence*100) }}%</strong><div class="progress-bar" style="width:90px;margin-top:5px"><i :style="{ width: `${memory.confidence * 100}%` }"></i></div></td><td>{{ memory.evidenceCount }} {{ $lt('refs') }}<br><small class="muted">{{ memory.revisions }} {{ $lt('revisions') }}</small></td><td><span v-for="agent in memory.usedBy" :key="agent" class="agent-mini">{{ agent==='claude-code'?'C':'X' }}</span></td><td><NButton text type="primary" @click="selected=memory">{{ $lt('Govern') }} →</NButton></td></tr></tbody></table></SectionCard>
  <NDrawer :show="!!selected" width="620" @update:show="v=>{if(!v)selected=null}"><NDrawerContent v-if="selected" :title="$lt('Memory evidence & lifecycle')" closable><div class="drawer-panel"><StatusBadge :status="selected.state"/><h3>{{ selected.claim }}</h3><dl class="kv-grid"><dt>{{ $lt('Memory ID') }}</dt><dd class="mono">{{ selected.id }}</dd><dt>{{ $lt('Scope') }}</dt><dd class="mono">{{ selected.scope }}</dd><dt>{{ $lt('Priority') }}</dt><dd>P{{ selected.priority }}</dd><dt>{{ $lt('Confidence') }}</dt><dd>{{ Math.round(selected.confidence*100) }}%</dd><dt>{{ $lt('Revision') }}</dt><dd>{{ selected.revisions }}</dd><dt>{{ $lt('Evidence') }}</dt><dd>{{ selected.evidenceCount }} {{ $lt('immutable references') }}</dd></dl><h4>{{ $lt('Revision timeline') }}</h4><div class="memory-history"><div><i></i><strong>{{ $lt('Current') }} · {{ $lt(selected.state) }}</strong><span>{{ selected.updatedAt }}</span></div><div><i></i><strong>{{ $lt('Evidence confirmed') }}</strong><span>{{ $lt('event refs merged and sorted') }}</span></div><div><i></i><strong>{{ $lt('Candidate created') }}</strong><span>{{ $lt('derived from session evidence') }}</span></div></div><div class="drawer-actions"><NButton @click="transition('contest')">{{ $lt('Contest') }}</NButton><NButton @click="transition('archive')">{{ $lt('Archive') }}</NButton><NButton type="error" secondary @click="transition('retract')">{{ $lt('Retract') }}</NButton><NButton type="primary" @click="transition('confirm')">{{ $lt('Confirm evidence') }}</NButton></div></div></NDrawerContent></NDrawer>
  <NModal :show="!!compact" preset="card" :title="$lt('Memory compaction preview')" style="width:620px" @update:show="v=>{if(!v)compact=null}"><div v-if="compact"><div class="three-column simulation"><div><strong>{{ compact.before }}</strong><span>{{ $lt('before') }}</span></div><div><strong>{{ compact.after }}</strong><span>{{ $lt('after') }}</span></div><div><strong>{{ compact.evidencePreserved }}%</strong><span>{{ $lt('evidence preserved') }}</span></div></div><div class="callout warning" style="margin-top:16px">{{ $lt('Compaction creates superseding memories and preserves every source revision. Nothing is physically deleted.') }}</div></div><template #footer><div style="display:flex;justify-content:flex-end;gap:8px"><NButton @click="compact=null">{{ $lt('Cancel') }}</NButton><NButton type="primary" @click="compact=null">{{ $lt('Create candidates') }}</NButton></div></template></NModal>
</div></template>

<style scoped>.memory-metrics{grid-template-columns:repeat(4,1fr)}.agent-mini{display:inline-grid;place-items:center;width:23px;height:23px;margin-right:-4px;border:2px solid var(--panel);border-radius:50%;background:#173128;color:var(--green);font:9px ui-monospace,monospace}.memory-history{border-left:1px solid var(--line);margin-left:6px}.memory-history div{position:relative;display:flex;flex-direction:column;padding:0 0 18px 20px}.memory-history i{position:absolute;left:-5px;top:3px;width:9px;height:9px;border-radius:50%;background:var(--green)}.memory-history strong{font-size:11px}.memory-history span{color:var(--muted);font-size:9px;margin-top:3px}.drawer-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.simulation div{padding:15px;background:var(--panel-2);border-radius:8px;text-align:center}.simulation strong{display:block;font-size:22px}.simulation span{color:var(--muted);font-size:9px}</style>
